import{_ as i,c as t,o as s,ae as o}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"ESTABLISHMENT OF THE RELIGIOUS LIBERTY COMMISSION","description":"","frontmatter":{"title":"ESTABLISHMENT OF THE RELIGIOUS LIBERTY COMMISSION","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/establishment-of-the-religious-liberty-commission/","publishDate":"2025-05-01T15:03:01-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-01-establishment-of-the-religious-liberty-commission.md","filePath":"executive-orders/2025-05-01-establishment-of-the-religious-liberty-commission.md"}'),r={name:"executive-orders/2025-05-01-establishment-of-the-religious-liberty-commission.md"};function l(n,e,a,u,m,c){return s(),t("div",null,e[0]||(e[0]=[o('<h1 id="establishment-of-the-religious-liberty-commission" tabindex="-1">ESTABLISHMENT OF THE RELIGIOUS LIBERTY COMMISSION <a class="header-anchor" href="#establishment-of-the-religious-liberty-commission" aria-label="Permalink to &quot;ESTABLISHMENT OF THE RELIGIOUS LIBERTY COMMISSION&quot;">​</a></h1><p>Published: Thursday, May 1, 2025</p><ul><li>The executive branch will enforce strong protections for religious liberty as enshrined in Federal law.</li><li>Religious liberty is presented as a fundamental right, rooted in the First Amendment and reflective of the Founders&#39; vision for America.</li><li>Recent policies at various government levels threaten religious liberty, including: <ul><li>Infringements on conscience protections.</li><li>Restrictions on parental rights regarding religious education.</li><li>Discriminatory treatment of religious organizations.</li></ul></li><li>Acknowledgement of the historical role of religions in civil rights movements and the provision of essential services.</li><li>Establishment of the <strong>Religious Liberty Commission</strong> with the following key details: <ul><li>Composed of up to 14 members appointed by the President, representing diverse sectors, including religious communities and educational institutions.</li><li>The Commission will serve until July 4, 2026, unless extended, and will provide a comprehensive report on the state of religious liberty in America.</li><li>Areas of focus include First Amendment rights, attacks on religious institutions, and parental authority in education.</li><li>Advisory Boards for religious leaders, lay leaders, and legal experts will support the Commission.</li><li>The Department of Justice will provide necessary support and funding.</li></ul></li><li>Any invalid provision will not affect the remainder of the order.</li><li>The order does not impair existing executive authority or functions related to budget or legislative proposals.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/establishment-of-the-religious-liberty-commission/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/establishment-of-the-religious-liberty-commission/</a></p>',4)]))}const p=i(r,[["render",l]]);export{h as __pageData,p as default};
